public static class METReasonFormTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Method to initialize the MET Invoice matching field group. 
    /// </summary>
    /// <param name="_this">ReasonFormTable instance</param>
    /// <param name="_reasonGridInvMatchGroup">Field group control</param>
    /// <returns>Invoice matching field group</returns>
    public static FormGroupControl parmReasonGridInvoiceMatchingGroup(ReasonFormTable _this, FormGroupControl _reasonGridInvMatchGroup = null)
    {
        FormGroupControl metInvMatchGroup = null;

        FormControlId metInvMatchGroupId = _this.parmReasonFormInstance().controlId(formControlStr(Reasons, METInvoiceMatching));
        if (metInvMatchGroup)
        {
            metInvMatchGroup = _this.parmReasonFormInstance().control(metInvMatchGroupId);
        }

        return metInvMatchGroup;
    }
